import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load the image texture
  const material = new MeshBasicNodeMaterial();
  let texturePromise = Promise.resolve();

  if (config.imageUrl) {
    texturePromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.colorNode = tex;
      material.needsUpdate = true;
    });
  }

  // ============================================================================
  // 2. MESH & GROUP
  // ============================================================================
  const mesh = new THREE.Mesh(geometry, material);
  const group = new THREE.Group();

  // Apply scene position from config (adapter will override if needed, but we set it here)
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? 3.2,
      config.scenePosition.y ?? -0.3,
      config.scenePosition.z ?? 0
    );
  } else {
    group.position.set(3.2, -0.3, 0);
  }

  if (config.sceneRotation) {
    group.rotation.set(
      config.sceneRotation.x ?? 0,
      config.sceneRotation.y ?? 0,
      config.sceneRotation.z ?? 0
    );
  }

  if (config.sceneScale) {
    group.scale.set(
      config.sceneScale.x ?? 1,
      config.sceneScale.y ?? 1,
      config.sceneScale.z ?? 1
    );
  }

  group.add(mesh);

  // ============================================================================
  // 3. INTERACTION STATE
  // ============================================================================
  const state = {
    isHovered: false,
    isPressed: false,
    baseY: group.position.y,
  };

  const timelines = [];

  // ============================================================================
  // 4. HOVER INTERACTION (rise-in: subtle 0.15 scene units)
  // ============================================================================
  const onPointerEnter = () => {
    if (state.isHovered) return;
    state.isHovered = true;

    // Kill any existing hover timeline
    timelines.forEach((tl) => {
      if (tl._tag === 'hover') tl.kill();
    });

    const hoverTl = gsap.timeline();
    hoverTl._tag = 'hover';

    // Subtle rise-in: translate +0.15 units in Y over 0.6s with power2.out easing
    hoverTl.to(
      group.position,
      {
        y: state.baseY + 0.15,
        duration: 0.6,
        ease: 'power2.out',
      },
      0
    );

    // Optional: slight tilt on hover (3-4 deg)
    hoverTl.to(
      group.rotation,
      {
        z: 0.05,
        duration: 0.6,
        ease: 'power2.out',
      },
      0
    );

    timelines.push(hoverTl);
  };

  const onPointerLeave = () => {
    if (!state.isHovered) return;
    state.isHovered = false;

    // Kill hover timeline
    timelines.forEach((tl) => {
      if (tl._tag === 'hover') tl.kill();
    });

    // Settle back with weighted-settle (overshoot 1.04 -> 1.0, power4.out)
    const settleTl = gsap.timeline();
    settleTl._tag = 'settle';

    settleTl.to(
      group.position,
      {
        y: state.baseY,
        duration: 0.9,
        ease: 'power4.out',
        overwrite: 'auto',
      },
      0
    );

    settleTl.to(
      group.rotation,
      {
        z: 0,
        duration: 0.9,
        ease: 'power4.out',
      },
      0
    );

    timelines.push(settleTl);
  };

  // ============================================================================
  // 5. CLICK INTERACTION (press-down + emit)
  // ============================================================================
  const onPointerDown = () => {
    state.isPressed = true;

    // Kill any existing press timeline
    timelines.forEach((tl) => {
      if (tl._tag === 'press') tl.kill();
    });

    const pressTl = gsap.timeline();
    pressTl._tag = 'press';

    // Scale 0.97 over 120ms with back.out
    pressTl.to(
      group.scale,
      {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      },
      0
    );

    timelines.push(pressTl);
  };

  const onPointerUp = () => {
    if (!state.isPressed) return;
    state.isPressed = false;

    // Emit journal selection event
    ctx.emit('hub-journal.select', { cardIndex: 3 });

    // Kill press timeline and settle scale back
    timelines.forEach((tl) => {
      if (tl._tag === 'press') tl.kill();
    });

    const releaseTl = gsap.timeline();
    releaseTl._tag = 'settle';

    releaseTl.to(
      group.scale,
      {
        x: 1,
        y: 1,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto',
      },
      0
    );

    timelines.push(releaseTl);
  };

  // ============================================================================
  // 6. USER DATA & EVENT HANDLERS
  // ============================================================================
  group.userData.handlers = {
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onPointerUp,
  };

  // ============================================================================
  // 7. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it exists
    if (material.colorNode && material.colorNode.dispose) {
      material.colorNode.dispose();
    }
  };

  return group;
}
